CREATE PROCEDURE TicketResolverRefreshTokenDeactivateAll @UserId INT AS BEGIN SET NOCOUNT ON; BEGIN TRY BEGIN TRANSACTION; UPDATE TicketResolverRefreshToken SET RevokedDate = GETDATE(), IsActive = 0, ModifiedDate = GETDATE() WHERE UserId = @UserId AND IsActive = 1; COMMIT TRANSACTION; END TRY BEGIN CATCH ROLLBACK TRANSACTION; THROW; END CATCH END
